/**
 * Padding on every side from one spacing preset.
 *
 * @param string $step Spacing preset slug.
 * @return array<string, string> Padding sides.
 */
function block_style_padding( string $step ): array {
	$value = 'var:preset|spacing|' . $step;
	return array(
		'top'    => $value,
		'right'  => $value,
		'bottom' => $value,
		'left'   => $value,
	);
}

